stages.sampleAnswer:
POST /trips
  body: { pickupLat, pickupLng, dropoffLat, dropoffLng, userId }
  → 200 { tripId, driverId, driverName, driverLat, driverLng, estimatedPickupEta }

GET /trips/:tripId
  → Trip { status, driverId, driverLat, driverLng, pickupEta }

POST /trips/:tripId/accept
  header: { Authorization: driverId }
  → 200 { tripId, status: 'accepted' }

WebSocket /trips/:tripId/stream-location
  → realtime driver location updates { lat, lng, timestamp }
